package com.franco.desco.adapter.in.web.campaign;import io.swagger.v3.oas.annotations.media.Schema;import jakarta.validation.constraints.*;import java.time.LocalDate;
public final class CampaignRequests{private CampaignRequests(){}@Schema(name="CampaignCreateRequest")public record Create(@NotNull Long asociacionId,@NotNull Long empresaCompradoraId,@NotBlank@Size(max=40)String codigo,@NotBlank@Size(max=180)String nombre,@NotNull LocalDate fechaInicio,@NotNull LocalDate fechaFin,@Size(max=400)String observacion){}@Schema(name="CampaignUpdateRequest")public record Update(@NotNull Long empresaCompradoraId,@NotBlank@Size(max=180)String nombre,@NotNull LocalDate fechaInicio,@NotNull LocalDate fechaFin,@Size(max=400)String observacion){}@Schema(name="CampaignTransitionRequest")public record Transition(@Size(max=500)String motivo){} }
